package com.fitconnect.notification.api; import com.fitconnect.notification.service.NotificationService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService s;public NotificationController(NotificationService s){this.s=s;}@PostMapping public ResponseEntity<NotificationResponse> create(@Valid @RequestBody NotificationRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping("/user/{id}") public List<NotificationResponse> user(@PathVariable Long id){return s.user(id);}@GetMapping("/pending") public List<NotificationResponse> pending(){return s.pending();}@PatchMapping("/{id}/retry") public NotificationResponse retry(@PathVariable Long id){return s.retry(id);}}
